export type DocsBlock =
  | { type: "p"; text: string }
  | { type: "h2"; text: string }
  | { type: "h3"; text: string }
  | { type: "ul"; items: string[] }
  | { type: "ol"; items: string[] }
  | { type: "callout"; tone: "info" | "warning" | "success"; title: string; text: string }
  | { type: "steps"; items: Array<{ title: string; body: string }> }
  | { type: "table"; headers: string[]; rows: string[][] };

export type DocsPage = {
  slug: string[];
  href: string;
  title: string;
  description: string;
  group: string;
  blocks: DocsBlock[];
};

function href(slug: string[]) {
  return slug.length ? `/docs/${slug.join("/")}` : "/docs";
}

function page(slug: string[], title: string, description: string, group: string, blocks: DocsBlock[]): DocsPage {
  return { slug, href: href(slug), title, description, group, blocks };
}

