export const DOCS_GROUPS = ["Getting started", "Established modules", "Growth modules", "Workspace"];

export function findDoc(slug: string[] | undefined) {
  const key = (slug ?? []).join("/");
  return DOCS_PAGES.find((page) => page.slug.join("/") === key) ?? null;
}
